'use client';

import { useEffect, useMemo, useState } from 'react';
import { Download, ExternalLink, Printer } from 'lucide-react';
import { loadLabel } from '@/lib/shipping';
import { buildLabelHtml, LABEL_CSS, printLabelHtml } from '@/lib/labelHtml';
import useWarehouses from '@/hooks/useWarehouses';
import Modal from '@/components/ui/Modal';
import Button from '@/components/ui/Button';
import Spinner from '@/components/ui/Spinner';
import Tabs from '@/components/ui/Tabs';

/**
 * Shipping label viewer.
 *  - "Courier label": the label generated by Xpressbees / Shipmozo / Ekart / Delhivery / Shiprocket, shown inside the CRM
 *  - "CRM label": a 4x6 label the CRM generates itself (barcode, ship-to, ship-from). Always available once there is an AWB.
 */
export default function LabelModal({ open, order, onClose }) {
  const wh = useWarehouses();
  const [tab, setTab] = useState('courier');
  const [state, setState] = useState({ loading: true, label: null, error: '' });

  useEffect(() => {
    if (!open || !order?._id) return undefined;
    let cancelled = false;
    let loaded = null;
    setTab('courier');
    setState({ loading: true, label: null, error: '' });
    loadLabel(order._id)
      .then((label) => {
        if (cancelled) { label.release(); return; }
        loaded = label;
        setState({ loading: false, label, error: '' });
      })
      .catch((err) => {
        if (cancelled) return;
        setState({ loading: false, label: null, error: err.message });
        setTab('crm'); // courier label unavailable: show the CRM label straight away
      });
    return () => { cancelled = true; loaded?.release(); };
  }, [open, order?._id]);

  const warehouse = wh.rows.find((w) => String(w._id) === String(order?.shipping?.warehouseId));
  const crmHtml = useMemo(() => (open && order ? buildLabelHtml({ order, warehouse }) : ''), [open, order, warehouse]);
  const { label, loading, error } = state;

  const printCourier = () => {
    if (label?.kind === 'pdf' && !label.external) {
      const w = window.open(label.src, '_blank');
      if (w) w.addEventListener('load', () => w.print());
    } else {
      window.open(label.src, '_blank');
    }
  };

  const footer = tab === 'crm' ? (
    <>
      <Button variant="secondary" onClick={onClose}>Close</Button>
      <Button icon={Printer} onClick={() => printLabelHtml(crmHtml)}>Print label</Button>
    </>
  ) : (
    <>
      <Button variant="secondary" onClick={onClose}>Close</Button>
      {label && (
        <>
          <a href={label.src} target="_blank" rel="noreferrer"><Button variant="secondary" icon={ExternalLink}>Open in new tab</Button></a>
          {!label.external && (
            <a href={label.src} download={`label-${order.shipping?.awb || order.orderId}.${label.kind === 'pdf' ? 'pdf' : 'png'}`}>
              <Button variant="secondary" icon={Download}>Download</Button>
            </a>
          )}
          <Button icon={Printer} onClick={printCourier}>Print</Button>
        </>
      )}
    </>
  );

  return (
    <Modal open={open} onClose={onClose} size="xl" title={`Shipping label · ${order?.shipping?.awb || order?.orderId || ''}`} footer={footer}>
      <div className="-mx-5 -mt-5 mb-4">
        <Tabs tabs={[{ value: 'courier', label: 'Courier label' }, { value: 'crm', label: 'CRM label (4x6)' }]} value={tab} onChange={setTab} />
      </div>

      {tab === 'courier' && (
        loading ? <Spinner /> : error ? (
          <div className="space-y-3 rounded-lg bg-warning-soft p-4 text-sm text-warning">
            <p>The courier label is not available yet: {error}</p>
            <Button variant="secondary" onClick={() => setTab('crm')}>Show the CRM label instead</Button>
          </div>
        ) : label.kind === 'image' ? (
          // eslint-disable-next-line @next/next/no-img-element
          <img src={label.src} alt="Shipping label" className="mx-auto max-h-[70vh] rounded-lg border border-border" />
        ) : (
          <iframe src={label.src} title="Shipping label" className="h-[70vh] w-full rounded-lg border border-border" />
        )
      )}

      {tab === 'crm' && (
        <div className="flex justify-center overflow-x-auto rounded-lg bg-surface-muted p-4">
          <style>{LABEL_CSS}</style>
          {order?.shipping?.awb || order?.courier?.awb
            ? <div dangerouslySetInnerHTML={{ __html: crmHtml }} />
            : <p className="text-sm text-muted">The AWB is not available yet. Press Refresh status to fetch it.</p>}
        </div>
      )}
    </Modal>
  );
}
